private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int startPos = i;
    try {
        // Read first byte of the next UTF‑8 sequence
        int b0 = bb.get() & 0xFF;
        i++; // consumed first byte

        // Single‑byte (ASCII) case
        if (b0 < 0x80) {
            sb.append((char) b0);
            return i;
        }

        // Determine number of leading 1 bits to identify sequence length
        int expectedLen = 0;
        int mask = 0x80;
        while ((b0 & mask) != 0) {
            expectedLen++;
            mask >>= 1;
        }

        // UTF‑8 spec limits sequence length to 4
        if (expectedLen < 2 || expectedLen > 4) {
            // Invalid leading byte, append replacement character
            sb.append('\uFFFD');
            return i;
        }

        int codePoint = b0 & (0xFF >> expectedLen);
        // Consume continuation bytes
        for (int k = 1; k < expectedLen; k++) {
            if (!bb.hasRemaining()) {
                // Truncated sequence – emit replacement character
                sb.append('\uFFFD');
                return i;
            }
            int byteVal = bb.get() & 0xFF;
            i++; // consumed this byte
            if ((byteVal & 0xC0) != 0x80) {
                // Invalid continuation byte
                sb.append('\uFFFD');
                return i;
            }
            codePoint = (codePoint << 6) | (byteVal & 0x3F);
        }
        sb.append(Character.toChars(codePoint));
    } catch (BufferUnderflowException e) {
        // No more bytes to decode; lower-level code will handle the end of the buffer
        return startPos;
    }
    return i;
}

int visitFrameStart(final int offset,final int numLocal,final int numStack){
    // Validate arguments
    if(offset < 0){
        throw new IllegalArgumentException("Offset must be non-negative: " + offset);
    }
    if(numLocal < 0){
        throw new IllegalArgumentException("Number of locals must be non-negative: " + numLocal);
    }
    if(numStack < 0){
        throw new IllegalArgumentException("Number of stack entries must be non-negative: " + numStack);
    }

    // Start a new frame.  The concrete type of currentFrame is expected to be a
    // class that holds offset, numLocal and numStack.  We assume it has a
    // constructor that matches these parameters.
    currentFrame = new StackMapFrame(offset, numLocal, numStack);

    // The next element to write in this frame is always the 0‑th slot (locals
    // come first, then stack values).  Return 0 to signal the caller that
    // writing should start there.
    return 0;
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    int currentCapacity = data.length;
    int requiredCapacity = length + size;
    int newCapacity = currentCapacity * 2;
    if (requiredCapacity > newCapacity) {
        newCapacity = requiredCapacity;
    }
    byte[] newData = new byte[newCapacity];
    System.arraycopy(data, 0, newData, 0, length);
    data = newData;
}

