public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments must not be null");
    }
    int size = schema.serializedSize(message);
    if (size < 0) {
        throw new IOException("Negative message size");
    }
    buffer.clear();
    schema.writeTo(buffer, message);
    byte[] bytes = buffer.getInternalByteArray();
    // Write length prefix as 4-byte big-endian
    out.write((size >>> 24) & 0xFF);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    out.write(bytes, 0, size);
    return size + 4;
}

