static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep<=0){ return timeBucket; }
    try{
        long year  = timeBucket/10000;
        long month = (timeBucket%10000)/100;
        long day   = timeBucket%100;
        if(day<=0){ return timeBucket; }
        long bucketStartDay = ((day-1)/dayStep)*dayStep + 1;
        return year*10000 + month*100 + bucketStartDay;
    }catch(Exception e){
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index or length out of bounds");
    }
    int size = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        char ch = str.charAt(i++);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else {
            if (ch >= 0xD800 && ch <= 0xDBFF && i < end) {
                char low = str.charAt(i);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    i++; // consume low surrogate
                    size += 4;
                    continue;
                }
            }
            size += 3;
        }
    }
    return size;
}

