public void removeFromTreeEdgeList(){
    // Remove from source node's edge list
    if (prevSrcEdge != null) {
        prevSrcEdge.nextSrcEdge = nextSrcEdge;
    }
    if (nextSrcEdge != null) {
        nextSrcEdge.prevSrcEdge = prevSrcEdge;
    }
    // Remove from destination node's edge list
    if (prevDstEdge != null) {
        prevDstEdge.nextDstEdge = nextDstEdge;
    }
    if (nextDstEdge != null) {
        nextDstEdge.prevDstEdge = prevDstEdge;
    }
    // Null out this edge's own pointers to help GC
    prevSrcEdge = nextSrcEdge = prevDstEdge = nextDstEdge = null;
}

public static String findAndSubst(String key, java.util.Properties props){
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and Properties must not be null");
    }
    try {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        // Perform ${var} style substitution
        java.util.regex.Pattern varPattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
        java.util.regex.Matcher matcher = varPattern.matcher(value);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                replacement = "";
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(sb);
        return sb.toString();
    } catch (Exception e) {
        // Log or handle as needed; for now wrap and rethrow as runtime
        throw new RuntimeException("Error while performing variable substitution", e);
    }
}

