public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int offset = 0;
    if (u.isAbsolute() && path.startsWith("/")) {
        offset = 1;
    }
    String trimmed = path.substring(offset);
    String[] parts = trimmed.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

