private void pop(final String descriptor) {
    if (descriptor == null) {
        return;
    }
    try {
        // Method descriptor: starts with '('
        if (descriptor.charAt(0) == '(') {
            int endParen = descriptor.indexOf(')');
            if (endParen < 0) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            int i = 1; // start after '('
            while (i < endParen) {
                char c = descriptor.charAt(i);
                int slots = 0;
                if (c == 'J' || c == 'D') {        // long or double
                    slots = 2;
                    i++;
                } else if (c == '[') {              // array type
                    // skip any number of '['
                    while (descriptor.charAt(i) == '[') {
                        i++;
                    }
                    // after '['s comes a type descriptor
                    if (descriptor.charAt(i) == 'L') {   // reference type
                        i = descriptor.indexOf(';', i) + 1;
                    } else {                            // primitive element type
                        i++;
                    }
                    slots = 1;
                } else if (c == 'L') {              // reference type
                    i = descriptor.indexOf(';', i) + 1;
                    slots = 1;
                } else {                            // primitive type
                    slots = 1;
                    i++;
                }
                // Pop the specified number of slots
                for (int s = 0; s < slots; s++) {
                    if (pos <= 0) {
                        throw new IllegalStateException("Stack underflow while popping descriptor");
                    }
                    stack[--pos] = null;  // clear reference for GC safety
                }
            }
        } else {
            // Single type descriptor
            int i = 0;
            char c = descriptor.charAt(i);
            int slots = 0;
            if (c == 'J' || c == 'D') {        // long or double
                slots = 2;
                i++;
            } else if (c == '[') {             // array type
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                if (descriptor.charAt(i) == 'L') {
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    i++;
                }
                slots = 1;
            } else if (c == 'L') {             // reference type
                i = descriptor.indexOf(';', i) + 1;
                slots = 1;
            } else {                           // primitive type
                slots = 1;
                i++;
            }
            for (int s = 0; s < slots; s++) {
                if (pos <= 0) {
                    throw new IllegalStateException("Stack underflow while popping descriptor");
                }
                stack[--pos] = null;
            }
        }
    } catch (StringIndexOutOfBoundsException ex) {
        throw new IllegalArgumentException("Malformed descriptor: " + descriptor, ex);
    }
}

