        double y = box.getY();
        double width = box.getWidth();
        double height = box.getHeight();
        if (width < 0 || height < 0) {
            throw new IllegalArgumentException("box dimensions must be non-negative");
        }
        double halfWidth = width / 2.0;
        Box2D first = new Box2D(x, y, halfWidth, height);
        Box2D second = new Box2D(x + halfWidth, y, halfWidth, height);
        return new Pair<>(first, second);
    } catch (RuntimeException e) {
        throw new IllegalArgumentException("Failed to split box: " + e.getMessage(), e);
    }
}

private void enlarge(final int size){
    if (size <= 0) {
        return;
    }
    int currentCap = data == null ? 0 : data.length;
    int needed = length + size;
    int newCap;
    if (currentCap == 0) {
        newCap = needed;
    } else {
        newCap = Math.max(currentCap * 2, needed);
    }
    byte[] newData = new byte[newCap];
    if (data != null && length > 0) {
        System.arraycopy(data, 0, newData, 0, length);
    }
    data = newData;
}

