@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Ensure the target type is Character or char
    if (!Character.class.isAssignableFrom(type) && !type.equals(char.class)) {
        throw new IllegalArgumentException("Target type is not a Character: " + type);
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() != 1) {
            throw new IllegalArgumentException(
                "Cannot convert String to Character: string length is " + str.length());
        }
        return str.charAt(0);
    }
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }
    if (value instanceof Boolean) {
        return ((Boolean) value) ? '1' : '0';
    }
    throw new IllegalArgumentException("Cannot convert value of type " + value.getClass() + " to Character");
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Ensure we start with an odd candidate
    int candidate = (desiredCapacity <= 2) ? 2 : (desiredCapacity % 2 == 0 ? desiredCapacity + 1 : desiredCapacity);
    // Compute upper bound: desiredCapacity + 11% if desiredCapacity >= 1000
    int bound = desiredCapacity;
    if (desiredCapacity >= 1000) {
        bound = desiredCapacity + desiredCapacity / 9; // ≈ +11%
        if (bound < candidate) bound = candidate; // just in case
    }
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
        if (desiredCapacity >= 1000 && candidate > bound) {
            // Should not happen normally; return candidate anyway
            return candidate;
        }
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    int limit = (int) Math.sqrt(n);
    for (int i = 5; i <= limit; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

