public final byte[] toByteArray(){
    if (buffers == null || buffers.isEmpty()){
        return new byte[0];
    }
    int total = 0;
    for (ByteBuffer buf : buffers){
        if (buf != null){
            total += buf.remaining();
        }
    }
    byte[] result = new byte[total];
    int offset = 0;
    for (ByteBuffer buf : buffers){
        if (buf == null) continue;
        ByteBuffer dup = buf.duplicate();
        int len = dup.remaining();
        dup.get(result, offset, len);
        offset += len;
    }
    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                sb.append('\\');
                continue;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape sequence \uXXXX
                    if (i + 5 >= len) {
                        throw new Exception("Invalid Unicode escape sequence at index " + i);
                    }
                    try {
                        String hex = str.substring(i + 2, i + 6);
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape digits at index " + i, e);
                    }
                    i += 5; // skip over 'uXXXX'
                    break;
                default:
                    // Preserve unknown escape as literal character
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

