private JsonObject convertProperties(List<KeyStringValuePair> properties){ 
    JsonObject result = new JsonObject(); 
    if (properties == null){ 
        return result; 
    } 
    com.google.gson.Gson gson = new com.google.gson.Gson(); 
    for (KeyStringValuePair pair : properties){ 
        if (pair == null){ 
            continue; 
        } 
        try{ 
            String key = pair.getKey(); 
            Object value = pair.getValue(); 
            if (key == null || value == null){ 
                continue; 
            } 
            if (value instanceof com.google.gson.JsonElement){ 
                result.add(key, (com.google.gson.JsonElement) value); 
            } else { 
                com.google.gson.JsonElement elem = gson.toJsonTree(value); 
                result.add(key, elem); 
            } 
        }catch (Exception e){ 
            // skip problematic entry 
        } 
    } 
    return result; 
}

