    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    if(offset + 2 + length > classFileBuffer.length){
        throw new IllegalArgumentException("constant pool entry exceeds class file buffer");
    }
    if(charBuffer == null){
        throw new NullPointerException("charBuffer");
    }
    if(charBuffer.length < length){
        throw new IllegalArgumentException("charBuffer too small for UTF-8 entry (needs "+length+" chars)");
    }
    for(int i=0;i<length;i++){
        charBuffer[i] = (char)(classFileBuffer[offset + 2 + i] & 0xFF);
    }
    return new String(charBuffer,0,length);
}

private static char decodeHexNibble(final char c) {
    if ('0' <= c && c <= '9') {
        return (char) (c - '0');
    } else if ('a' <= c && c <= 'f') {
        return (char) (c - 'a' + 10);
    } else if ('A' <= c && c <= 'F') {
        return (char) (c - 'A' + 10);
    } else {
        return Character.MAX_VALUE;
    }
}

public static long factorial(int n){ 
    if (n < 0) { 
        throw new IllegalArgumentException("n must be non-negative"); 
    } 
    long result = 1L; 
    for (int i = 2; i <= n; i++) { 
        if (result > Long.MAX_VALUE / i) { 
            throw new ArithmeticException("long overflow during factorial calculation"); 
        } 
        result *= i; 
    } 
    return result; 
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }

    // Create a circulator starting at `start` and marching in the given direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Keep advancing until we hit the stop node or find a node satisfying the predicate.
    while (!circ.getNode().equals(stop) && !predicate.test(circ.getNode())) {
        circ.next(dir);           // Advance one step in the requested direction.
    }

    return circ;
}

