    if ( byteLength < 0 ) {
        throw new IllegalArgumentException( "byteLength must be non-negative, got " + byteLength );
    }
    if ( byteOffset < 0 ) {
        throw new IllegalArgumentException( "byteOffset must be non-negative, got " + byteOffset );
    }
    if ( byteArrayValue != null && byteArrayValue.length < byteOffset + byteLength ) {
        throw new IllegalArgumentException(
            "byteArrayValue does not contain enough bytes: offset " + byteOffset + ", length " + byteLength );
    }

    int loc0 = this.length;
    // Ensure capacity
    if ( loc0 + byteLength > data.length ) {
        enlarge( byteLength );
    }

    if ( byteArrayValue == null ) {
        // put byteLength nullbytes (zeros)
        for ( int i = 0; i < byteLength; i++ ) {
            data[ loc0 + i ] = 0;
        }
    } else {
        // copy from provided array
        System.arraycopy( byteArrayValue, byteOffset, data, loc0, byteLength );
    }

    this.length = loc0 + byteLength;
    return this;
}

