protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null || tour.isEmpty()) return null;
    try{
        // Validate edges belong to graph and build adjacency
        Map<V, List<E>> adj = new HashMap<>();
        for (E e : tour) {
            if (!graph.containsEdge(e)) return null;
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            adj.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
            adj.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
        }
        // Find starting vertex (degree 1 if possible, else any)
        V start = null;
        for (Map.Entry<V, List<E>> entry : adj.entrySet()){
            if (entry.getValue().size() == 1){
                start = entry.getKey();
                break;
            }
        }
        if (start == null){
            // cycle; pick arbitrary vertex
            start = adj.keySet().iterator().next();
        }
        // Build path
        List<V> vertices = new ArrayList<>();
        List<E> edges = new ArrayList<>();
        Set<E> remaining = new LinkedHashSet<>(tour);
        V current = start;
        V prev = null;
        while (!remaining.isEmpty()){
            List<E> neighEdges = adj.get(current);
            if (neighEdges == null) break;
            E nextEdge = null;
            for (E e : neighEdges){
                if (remaining.contains(e)){
                    nextEdge = e;
                    break;
                }
            }
            if (nextEdge == null) break;
            remaining.remove(nextEdge);
            vertices.add(current);
            edges.add(nextEdge);
            V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                            ? graph.getEdgeTarget(nextEdge)
                            : graph.getEdgeSource(nextEdge);
            prev = current;
            current = nextVertex;
        }
        // Add final vertex
        vertices.add(current);
        if (remaining.size() > 0){
            // path incomplete; invalid set
            return null;
        }
        double weight = 0.0;
        for (E e : edges){
            weight += graph.getEdgeWeight(e);
        }
        return new DefaultGraphPath<>(graph, vertices.get(0), vertices.get(vertices.size()-1), edges, weight);
    }catch(Exception ex){
        return null;
    }
}

