private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(input.length());
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c != '\\') {
            result.append(c);
            i++;
            continue;
        }
        // reached a backslash
        i++;
        if (i >= input.length()) {
            // trailing backslash, keep it
            result.append('\\');
            break;
        }
        char next = input.charAt(i);
        if (next == 'u') {
            int j = i + 1;
            int hexLen = 0;
            while (j < input.length() && hexLen < 4 && isHexDigit(input.charAt(j))) {
                j++;
                hexLen++;
            }
            if (hexLen > 0) {
                String hex = input.substring(i + 1, j);
                try {
                    int codePoint = Integer.parseInt(hex, 16);
                    result.append((char) codePoint);
                } catch (NumberFormatException e) {
                    // if parsing fails, treat literal
                    result.append('u').append(hex);
                }
                i = j;
            } else {
                result.append('u');
                i++;
            }
        } else if (next == 'x') {
            int j = i + 1;
            int hexLen = 0;
            while (j < input.length() && hexLen < 2 && isHexDigit(input.charAt(j))) {
                j++;
                hexLen++;
            }
            if (hexLen > 0) {
                String hex = input.substring(i + 1, j);
                try {
                    int codePoint = Integer.parseInt(hex, 16);
                    result.append((char) codePoint);
                } catch (NumberFormatException e) {
                    result.append('x').append(hex);
                }
                i = j;
            } else {
                result.append('x');
                i++;
            }
        } else if (Character.isDigit(next)) {
            int j = i;
            int octLen = 0;
            while (j < input.length() && octLen < 3 && Character.isDigit(input.charAt(j)) && input.charAt(j) < '8') {
                j++;
                octLen++;
            }
            String oct = input.substring(i, j);
            try {
                int codePoint = Integer.parseInt(oct, 8);
                result.append((char) codePoint);
            } catch (NumberFormatException e) {
                result.append(oct);
            }
            i = j;
        } else {
            // regular escaped character
            result.append(next);
            i++;
        }
    }
    return result.toString();
}

private boolean isHexDigit(char ch) {
    return (ch >= '0' && ch <= '9')
        || (ch >= 'a' && ch <= 'f')
        || (ch >= 'A' && ch <= 'F');
}

