private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate inputs
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    if (minLabel == 0) {
        // Moving from bucket 0 to bucket 0 would clear all vertices; no-op
        return;
    }
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        return;
    }
    // Ensure bucket 0 exists
    if (bucketsByLabel.isEmpty()) {
        bucketsByLabel.add(new java.util.HashSet<Integer>());
    } else if (bucketsByLabel.get(0) == null) {
        bucketsByLabel.set(0, new java.util.HashSet<Integer>());
    }
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    for (Integer vertex : minBucket) {
        if (vertex >= 0 && vertex < labels.size()) {
            try {
                labels.set(vertex, 0);
            } catch (IndexOutOfBoundsException e) {
                // Ignore vertices with invalid label indices
            }
        }
    }
    zeroBucket.addAll(minBucket);
    minBucket.clear();
}

