private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }
    try {
        // adjust links for first node
        if (node.prev == null && node == first) {
            first = node.next;
            if (first != null) {
                first.prev = null;
            } else {
                last = null; // list became empty
            }
        }
        // adjust links for last node
        else if (node.next == null && node == last) {
            last = node.prev;
            if (last != null) {
                last.next = null;
            } else {
                first = null; // list became empty
            }
        }
        // adjust links for middle node
        else {
            if (node.prev != null) {
                node.prev.next = node.next;
            }
            if (node.next != null) {
                node.next.prev = node.prev;
            }
        }
        // clean up node references
        node.prev = null;
        node.next = null;
        size--;
        return true;
    } catch (Exception e) {
        // log the exception if a logger is available
        if (log != null) {
            log.error("Failed to unlink node: {}", e.getMessage(), e);
        }
        return false;
    }
}

public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int lastSlash = path.lastIndexOf('/');
    int lastBackSlash = path.lastIndexOf('\\');
    int lastSeparator = Math.max(lastSlash, lastBackSlash);
    int lastDot = path.lastIndexOf('.');
    if (lastDot == -1 || lastDot <= lastSeparator) {
        return null;
    }
    // Treat files that start with a dot and have no other separators as having no extension
    if (lastDot == 0 && lastSeparator < 0) {
        return null;
    }
    return path.substring(0, lastDot);
}

