private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    // Initialize list with placeholder values
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    long suffixRunning = 0L;
    for (int i = n - 1; i >= 0; i--) {
        suffixRunning += bounds.get(i);
        suffix.set(i, (int) suffixRunning);
    }
    long totalSum = suffixRunning;
    return new Pair<>(suffix, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }
    int len = arr.length;
    if (len == 0) {
        return;
    }
    if (from < 0 || to >= len || from > to) {
        throw new IndexOutOfBoundsException("Invalid from/to indices");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
