            if (node == null) break; // defensive check
            list.removeListNode(node);   // atomically remove from source
            this.addListNode(node);      // atomically add to destination
        }
    } catch (Exception ignore) {
        // If any exception occurs we leave the remaining nodes untouched
    }
}

