public static String applyRelativePath(String path, String relativePath) {
    try {
        if (path == null) {
            return null;
        }
        if (relativePath == null) {
            relativePath = "";
        }

        // Use a stack to resolve path components
        Deque<String> stack = new ArrayDeque<>();

        // Split the base path
        String[] baseParts = path.split("/", -1);
        boolean baseStartsWithSlash = path.startsWith("/");
        if (baseStartsWithSlash) {
            // Preserve leading slash by pushing an empty string as a placeholder
            stack.push("");
        }

        int baseEndIndex = baseParts.length;
        boolean pathEndsWithSlash = path.endsWith("/") || baseParts.length == 0;
        if (!pathEndsWithSlash && baseEndIndex > 0) {
            // Remove the file component if base path points to a file
            baseEndIndex -= 1;
        }

        for (int i = 0; i < baseEndIndex; i++) {
            String part = baseParts[i];
            if (part.isEmpty() || part.equals(".")) {
                // Skip empty or current directory references
                continue;
            } else if (part.equals("..")) {
                if (!stack.isEmpty() && !stack.peek().isEmpty()) {
                    stack.pop();
                }
            } else {
                stack.push(part);
            }
        }

        // Now apply the relative path components
        String[] relParts = relativePath.split("/", -1);
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            } else if (part.equals("..")) {
                if (!stack.isEmpty() && !stack.peek().isEmpty()) {
                    stack.pop();
                }
            } else {
                stack.push(part);
            }
        }

        // Build the final path string
        if (stack.isEmpty()) {
            return "/";
        }

        List<String> reversed = new ArrayList<>(stack);
        Collections.reverse(reversed);
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < reversed.size(); i++) {
            String comp = reversed.get(i);
            if (i == 0 && comp.isEmpty()) {
                result.append("/");
            } else {
                if (result.length() > 0 && result.charAt(result.length() - 1) != '/') {
                    result.append("/");
                }
                result.append(comp);
            }
        }

        // Ensure that a trailing slash is preserved if the original path ended with one
        if (path.endsWith("/") && !result.toString().endsWith("/")) {
            result.append("/");
        }

        return result.toString();
    } catch (Exception e) {
        throw new RuntimeException("Failed to apply relative path", e);
    }
}

