    for (Object obj : array) {
        if (obj == null) {
            nullCount++;
        }
    }
    if (nullCount == 0 && array instanceof String[]) {
        return (String[]) array;
    }
    int newSize = array.length - nullCount;
    String[] result = new String[newSize];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[idx++] = (String) obj;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int lastDotIndex = filename.lastIndexOf('.');
    if (lastDotIndex == -1) {
        return -1;
    }
    int lastSeparatorIndex = -1;
    for (int i = 0; i < filename.length(); i++) {
        char c = filename.charAt(i);
        if (c == '/' || c == '\\') {
            lastSeparatorIndex = i;
        }
    }
    return lastSeparatorIndex > lastDotIndex ? -1 : lastDotIndex;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    try{
        if(expiredThreshold <= 0){
            // Non-positive threshold means never expire
            return false;
        }
        // If we cannot get current time, consider it expired
        long now = System.currentTimeMillis();
        return (now - timestamp) > expiredThreshold;
    } catch(Exception e){
        // In case of any unexpected error, be safe and mark as expired
        return true;
    }
}

