        return "bytes "+start+"-"+end+"/"+total;
    }else{
        return "bytes "+start+"-"+end+"/*";
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.canRead()) {
        throw new IllegalArgumentException("Provided file is null, does not exist, or is not readable.");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return Collections.emptyList();
    }
    List<ThreadSnapshot> allSnapshots;
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        Object obj = ois.readObject();
        if (!(obj instanceof List<?>)) {
            throw new IOException("File content is not a List of ThreadSnapshot objects.");
        }
        @SuppressWarnings("unchecked")
        List<ThreadSnapshot> tmp = (List<ThreadSnapshot>) obj;
        allSnapshots = tmp;
    } catch (ClassNotFoundException e) {
        throw new IOException("Failed to load ThreadSnapshot class during deserialization.", e);
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        if (snapshot == null) {
            continue;
        }
        long ts;
        try {
            ts = snapshot.getTimestamp(); // assume ThreadSnapshot has this method
        } catch (Exception e) {
            // If snapshot doesn't expose a timestamp, skip it
            continue;
        }
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range == null) {
                continue;
            }
            try {
                long start = range.getStartTime(); // assume method
                long end = range.getEndTime();     // assume method
                if (ts >= start && ts <= end) {
                    result.add(snapshot);
                    break;
                }
            } catch (Exception ignore) {
                // if range doesn't expose times, treat as invalid and skip
            }
        }
    }
    return result;
}
